        private static void doEcoute(Object data) {
            // خيط الاستماع لطلبات العملاء
            try {
                // إنشاء الخدمة
                service = new TcpListener(IPAddress.Any, port);
                // تشغيلها
                service.Start();
                // الخادم نشط
                actif = true;
                // المتابعة
                Console.WriteLine("Serveur de calcul d'impôt lancé sur le port {0}", port);
                // حلقة خدمة العملاء
                TcpClient tcpClient = null;
                // رقم العميل
                int numClient = 0;
                // حلقة لا نهائية
                while (true) {
                    // في انتظار عميل
                    tcpClient = service.AcceptTcpClient();
                    // يتم توفير الخدمة بواسطة مهمة أخرى
                    ThreadPool.QueueUserWorkItem(doService, new Client() { CanalTcp = tcpClient, NumClient = numClient });
                    // العميل التالي
                    numClient++;
                }
            } catch (Exception ex) {
                // الإبلاغ عن الخطأ
                Console.WriteLine("L'erreur suivante s'est produite sur le serveur : {0}", ex.Message);
            }
        }

        // معلومات العميل
        internal class Client {
            public TcpClient CanalTcp { get; set; }        // الاتصال بالعميل
            public int NumClient { get; set; }            // رقم العميل
}
</code></pre> <p>لدينا هنا كود مشابه لكود خادم الصدى الذي تمت دراسته في الفقرة 11.6.1. سنعلق فقط على ما هو مختلف:</p> <ul> <li>السطر 7: تم إطلاق خدمة الاستماع   </li> <li>الخط 9: نلاحظ أن الخدمة أصبحت نشطة الآن   </li> </ul> <p>الخط 21، يتم خدمة العملاء بواسطة مؤشرات ترابط الخدمة التي تنفذ الطريقة التالية doService:</p> <pre><code>
private static void doService(Object infos) {
            // استرداد العميل المطلوب خدمته
            Client client = infos as Client;
            // تقديم الخدمة للعميل
            Console.WriteLine("Début du service au client {0}", client.NumClient);
            // تشغيل الاتصال TcpClient
            try {
                using (TcpClient tcpClient = client.CanalTcp) {
                    using (NetworkStream networkStream = tcpClient.GetStream()) {
                        using (StreamReader reader = new StreamReader(networkStream)) {
                            using (StreamWriter writer = new StreamWriter(networkStream)) {
                                // تدفق الإخراج غير المخزن مؤقتًا
                                writer.AutoFlush = true;
                                // إرسال رسالة ترحيب إلى العميل
                                writer.WriteLine("Bienvenue sur le serveur de calcul de l'impôt");
                                // حلقة قراءة الطلب/كتابة الرد
                                string demande = null;
                                bool serviceFini = false;
                                while (!serviceFini &amp;&amp; (demande = reader.ReadLine()) != null) {
                                    // متابعة وحدة التحكم
                                    if (echo) {
                                        Console.WriteLine("&lt;--- Client {0} : {1}", client.NumClient, demande);
                                    }
                                    // تحليل الطلب
                                    demande = demande.Trim().ToLower();
                                    // طلب فارغ؟
                                    if (demande.Length == 0) {
                                        // طلب خاطئ
                                        writeClient(writer,client.NumClient,"Commande non reconnue. Utilisez la commande aide.");
                                        return;
                                    }

                                    // تفكيك الطلب إلى حقول
                                    string[] champs = Regex.Split(demande, @"\s+");
                                    // تحليل
                                    switch (champs[0].ToLower()) {
                                        case "aide":
                                            writeClient(writer, client.NumClient, "Commandes acceptées\n1-aide\n2-impot marié(O/N) nbEnfants salaireAnnuel\n3-aurevoir");
                                            break;
                                        case "impot":
                                            // يتم حساب الضريبة
                                            writeClient(writer, client.NumClient, calculImpot(writer, client.NumClient, champs));
                                            break;
                                        case "aurevoir":
                                            serviceFini = true;
                                            writeClient(writer, client.NumClient, "Au revoir...");
                                            break;
                                        default:
                                            writeClient(writer, client.NumClient, "Commande non reconnue. Utilisez la commande aide.");
                                            break;
                                    }
                                }
                            }
                        }
                    }
                }
            } catch (Exception e) {
                // خطأ
                Console.WriteLine("L'erreur suivante s'est produite lors du service au client {0} : {1}", client.NumClient, e.Message);
            } finally {
                Console.WriteLine("Fin du service au client {0}", client.NumClient);
            }
        }

        private static void writeClient(StreamWriter writer, int numClient, string message) {
            // صدى وحدة التحكم؟
            if (echo) {
                Console.WriteLine("---&gt; Client {0} : {1}", numClient, message);
            }
            // إرسال رسالة إلى العميل
            writer.WriteLine(message);
}
</code></pre> <p>مرة أخرى، لدينا هنا كود مشابه لكود خادم الصدى الذي تمت دراسته في الفقرة 11.6.1. لن نعلق إلا على ما هو مختلف:</p> <ul> <li>السطر 15: بمجرد اتصال العميل، يرسل له الخادم رسالة ترحيب.   </li> <li>الأسطر 19-52: حلقة قراءة أوامر العميل. تتوقف الحلقة عندما يرسل العميل الأمر "aurevoir".   </li> <li>السطر 27: حالة الأمر الفارغ   </li> <li>السطر 34: يتم تقسيم الطلب إلى حقول لتحليله   </li> <li>السطر 37: الأمر aide: يطلب العميل قائمة بالأوامر المسموح بها   </li> <li>السطر 40: الأمر impot: يطلب العميل حساب الضريبة. يتم الرد بالرسالة التي تعيدها الطريقة calculImpot التي سنفصلها لاحقًا.   </li> <li>السطر 44: الأمر aurevoir: يشير العميل إلى أنه قد انتهى.   </li> <li>السطر 45: نستعد للخروج من حلقة قراءة طلبات العملاء (السطور 19-52)   </li> <li>السطر 46: نرد على العميل برسالة وداع   </li> <li>السطر 48: أمر غير صحيح. نرسل إلى العميل رسالة خطأ.   </li> </ul> <p>يتم معالجة الأمر impot بواسطة الطريقة calculImpot التالية:</p> <pre><code>
private static string calculImpot(StreamWriter writer, int numClient, string[] champs) {
            // طلب تحديد الحالة الاجتماعية (متزوج/غير متزوج) nbEnfants salaireAnnuel
            // يلزم 4 حقول
            if (champs.Length != 4) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // الحقول [1]
            string marié = champs[1];
            if (marié != "o" &amp;&amp; marié != "n") {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // الحقول [2]
            int nbEnfants;
            if (!int.TryParse(champs[2], out nbEnfants)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // الحقول [3]
            int salaireAnnuel;
            if (!int.TryParse(champs[3], out salaireAnnuel)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // حسناً - نحسب الضريبة
            int impot = 0;
            try {
                impot = metier.CalculerImpot(marié == "o", nbEnfants, salaireAnnuel);
                return impot.ToString();
            } catch (Exception ex) {
                return ex.Message;
            }
